33	template <> Status CreateOperation(const infer::ActivationParam &opParam, Operation **operation)
34	{
35	    if (operation == nullptr) {
36	        return ERROR_INVALID_PARAM;
37	    }
38	    OP_PARAM_RSV_CHECK(opParam);
39	    if (opParam.activationType <= atb::infer::ActivationType::ACTIVATION_UNDEFINED ||
40	        opParam.activationType >= atb::infer::ActivationType::ACTIVATION_MAX) {
41	        ATB_LOG(ERROR) << "activationType:" << opParam.activationType << "is invalid ActivationType";
42	        return ERROR_INVALID_PARAM;
43	    }
44	    if (opParam.dim != -1) {
45	        if ((opParam.activationType == atb::infer::ActivationType::ACTIVATION_SWIGLU_FORWARD ||
46	             opParam.activationType == atb::infer::ActivationType::ACTIVATION_SWIGLU_BACKWARD)) {
47	            ATB_LOG(ERROR) << "activationType: " << opParam.activationType << " only support splitting dim -1";
48	        } else {
49	            ATB_LOG(ERROR) << "activationType: " << opParam.activationType << " does not support splitting dim";
50	        }
51	        return ERROR_INVALID_PARAM;
52	    }
53	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
54	        if (opParam.activationType == atb::infer::ActivationType::ACTIVATION_GELU) {
55	            Status status = GeluAclnnRunner::LoadMethod();
56	            if (status != NO_ERROR) {
57	                ATB_LOG(ERROR) << "load GELU aclnn funcs failed.";
58	                return ERROR_CANN_ERROR;
59	            }
60	        } else if (opParam.activationType == atb::infer::ActivationType::ACTIVATION_SWISH ||
61	                   opParam.activationType == atb::infer::ActivationType::ACTIVATION_SIGMOID) {
62	            Status status = ActivationAclnnRunner::LoadAclnnFunctions();
63	            if (status != NO_ERROR) {
64	                ATB_LOG(ERROR) << "load aclnn funcs failed.";
65	                return ERROR_CANN_ERROR;
66	            }
67	        } else if (opParam.activationType == atb::infer::ActivationType::ACTIVATION_SWIGLU_FORWARD) {
68	            Status status = SwigluForwardAclnnRunner::LoadMethod();
69	            if (status != NO_ERROR) {
70	                ATB_LOG(WARN) << "Load Aclnn functions failed!";
71	                return ERROR_CANN_ERROR;
72	            }
73	        } else {
74	            ATB_LOG(ERROR) << "activationType: " << opParam.activationType << " is not yet supported.";
75	            return ERROR_INVALID_PARAM;
76	        }
77	    }
78	
79	    *operation = new (std::nothrow) ActivationOperation(opParam);
80	    if (*operation == nullptr) {
81	        ATB_LOG(ERROR) << "failed to new operation";
82	        return ERROR_OUT_OF_HOST_MEMORY;
83	    }
84	    return NO_ERROR;
85	}
