94	        case atb::infer::ActivationType::ACTIVATION_GELU:
95	            return GetSingleton<AtbOperationIrCfg>().GetOperationIr("ActivationOperationGELU");
96	        case atb::infer::ActivationType::ACTIVATION_SWIGLU_FORWARD:
97	            return GetSingleton<AtbOperationIrCfg>().GetOperationIr("ActivationOperationSWIGLUFORWARD");
98	        case atb::infer::ActivationType::ACTIVATION_FAST_GELU:
99	            return GetSingleton<AtbOperationIrCfg>().GetOperationIr("ActivationOperationFASTGELU");
100	        case atb::infer::ActivationType::ACTIVATION_SIGMOID:
101	            return GetSingleton<AtbOperationIrCfg>().GetOperationIr("ActivationOperationSIGMOID");
102	        case atb::infer::ActivationType::ACTIVATION_SWISH:
