160	Status ActivationOperation::CheckSwigluBackwardInTensor(const SVector<TensorDesc> &inTensorDescs) const
161	{
162	    int32_t dimNums = static_cast<int32_t>(inTensorDescs.at(0).shape.dimNum);
163	    int32_t splitDim = param_.dim < 0 ? param_.dim + dimNums : param_.dim;
164	    if (splitDim < 0 || splitDim >= dimNums) {
165	        ATB_LOG(ERROR) << "The value of attr [dim] must be in the range [-" << dimNums << ", " << (dimNums - 1)
166	                       << "], but got [" << splitDim << "].";
167	        return ERROR_INVALID_PARAM;
168	    }
169	    if (inTensorDescs.at(0).shape.dimNum != inTensorDescs.at(1).shape.dimNum) {
170	        ATB_LOG(ERROR) << "inTensor0 & inTensor1 dimNum does not match, should be same";
171	        return ERROR_INVALID_TENSOR_DIM;
172	    }
173	    for (uint64_t i = 0; i < inTensorDescs.at(0).shape.dimNum; i++) {
174	        if (static_cast<uint64_t>(splitDim) == i) {
175	            if (inTensorDescs.at(1).shape.dims[i] != SPLIT_NUM * inTensorDescs.at(0).shape.dims[i]) {
176	                ATB_LOG(ERROR) << GetLogPrefix() << "Dims[" << i << "] of inTensor0 should be half of inTensor1.";
177	                return ERROR_INVALID_TENSOR_DIM;
178	            }
179	        } else {
180	            if (inTensorDescs.at(0).shape.dims[i] != inTensorDescs.at(1).shape.dims[i]) {
181	                ATB_LOG(ERROR) << GetLogPrefix() << "Dims[" << i
182	                               << "] of inTensor0 and inTensor1 does not match, should be same.";
183	                return ERROR_INVALID_TENSOR_DIM;
184	            }
185	        }
186	    }
187	    return NO_ERROR;
188	}
189	
190	Status ActivationOperation::CheckSwigluForwardInTensor(const SVector<TensorDesc> &inTensorDescs) const
191	{
192	    int32_t splitDim = param_.dim;
193	    int32_t dimNums = inTensorDescs.at(0).shape.dimNum; // 0: x
194	    if (splitDim < 0) {
195	        splitDim += dimNums;
196	    }
197	    if (splitDim < 0 || splitDim >= dimNums) {
198	        ATB_LOG(ERROR) << "The value of param [dim] must be in the range [-" << dimNums << ", " << (dimNums - 1)
199	                       << "], but got [" << splitDim << "].";
200	        return ERROR_INVALID_PARAM;
201	    }
202	    int32_t hiddenSizeDimNums = inTensorDescs.at(0).shape.dims[dimNums - 1]; // dimNums - 1: hiddenSize
203	    if (GetSingleton<Config>().Is310P() && hiddenSizeDimNums % HIDDEN_SIZE_DIM_BASE != 0) {
204	        ATB_LOG(ERROR) << "Atlas inference products only support inTensor[0] with last dim "
205	                       << "being multiple of 32, but got " << hiddenSizeDimNums;
206	        return ERROR_INVALID_TENSOR_DIM; // HIDDEN_SIZE_DIM_BASE: multiple of 32
207	    }
208	    return NO_ERROR;
209	}
