211	Status ActivationOperation::InferShapeCheckImpl(const SVector<TensorDesc> &inTensorDescs) const
212	{
213	    if (param_.activationType == atb::infer::ActivationType::ACTIVATION_SWIGLU_BACKWARD) {
214	        return CheckSwigluBackwardInTensor(inTensorDescs);
215	    }
216	    if (param_.activationType == atb::infer::ActivationType::ACTIVATION_SWIGLU_FORWARD) {
217	        return CheckSwigluForwardInTensor(inTensorDescs);
218	    }
219	    return NO_ERROR;
220	}
221	
222	Status ActivationOperation::InferShapeImpl(const SVector<TensorDesc> &inTensorDescs,
223	                                           SVector<TensorDesc> &outTensorDescs) const
224	{
225	    if (param_.activationType == atb::infer::ActivationType::ACTIVATION_SWIGLU_FORWARD) {
226	        int32_t splitDim = param_.dim;
227	        int32_t dimNums = inTensorDescs.at(0).shape.dimNum; // 0: x
228	        if (splitDim < 0) {
229	            splitDim += dimNums;
230	        }
231	        outTensorDescs.at(0) = inTensorDescs.at(0); // 0: x
232	        outTensorDescs.at(0).shape.dims[splitDim] = inTensorDescs.at(0).shape.dims[splitDim] / SPLIT_NUM;
233	    } else if (param_.activationType == atb::infer::ActivationType::ACTIVATION_SWIGLU_BACKWARD) {
234	        outTensorDescs.at(0) = inTensorDescs.at(1); // // 0: y_grad, 1: x
235	    } else {
236	        outTensorDescs.at(0) = inTensorDescs.at(0);
237	    }
238	    return NO_ERROR;
239	}
