241	Status ActivationOperation::SetupCheckImpl(const SVector<Tensor> &inTensors, const SVector<Tensor> &outTensors) const
242	{
243	    SVector<TensorDesc> inTensorDescs = {};
244	    OperationUtil::InTensorsToInTensorDescs(inTensors, inTensorDescs);
245	    if (inTensors.at(0).desc.shape.dimNum != outTensors.at(0).desc.shape.dimNum) {
246	        ATB_LOG(ERROR) << "inTensor/outTensor dimNum does not match, should be same";
247	        return ERROR_INVALID_TENSOR_DIM;
248	    }
249	    if (param_.activationType != atb::infer::ActivationType::ACTIVATION_SWIGLU_BACKWARD &&
250	        param_.activationType != atb::infer::ActivationType::ACTIVATION_SWIGLU_FORWARD) {
251	        for (uint64_t i = 0; i < inTensors.at(0).desc.shape.dimNum; i++) {
252	            if (inTensors.at(0).desc.shape.dims[i] != outTensors.at(0).desc.shape.dims[i]) {
253	                ATB_LOG(ERROR) << GetLogPrefix() << "inTensor/outTensor dims does not match, should be same";
254	                return ERROR_INVALID_TENSOR_DIM;
255	            }
256	        }
257	        return NO_ERROR;
258	    }
259	    // Swiglu
260	    if (param_.activationType == atb::infer::ActivationType::ACTIVATION_SWIGLU_BACKWARD) {
261	        return CheckSwigluBackwardInTensor(inTensorDescs);
262	    }
263	    Status st;
264	    if ((st = CheckSwigluForwardInTensor(inTensorDescs)) != NO_ERROR) {
265	        return st;
266	    }
267	    int32_t dimNums = static_cast<int32_t>(inTensorDescs.at(0).shape.dimNum);
268	    int32_t splitDim = param_.dim < 0 ? param_.dim + dimNums : param_.dim;
269	    for (int32_t i = 0; i < dimNums; ++i) {
270	        if (i == splitDim) {
271	            if (SPLIT_NUM * outTensors.at(0).desc.shape.dims[splitDim] != inTensors.at(0).desc.shape.dims[splitDim]) {
272	                ATB_LOG(ERROR) << GetLogPrefix() << "outTensor dims[" << splitDim
273	                               << "] should be half of inTensor dims[" << splitDim << "]";
274	                return ERROR_INVALID_TENSOR_DIM;
275	            }
276	        } else if (outTensors.at(0).desc.shape.dims[i] != inTensors.at(0).desc.shape.dims[i]) {
277	            ATB_LOG(ERROR) << GetLogPrefix() << "Dims[" << i
278	                           << "] of inTensor0 and inTensor1 does not match, should be same.";
279	            return ERROR_INVALID_TENSOR_DIM;
280	        }
281	    }
282	    return NO_ERROR;
283	}
