285	std::shared_ptr<Runner> ActivationOperation::CreateRunner(Context &context) const
286	{
287	    (void)context;
288	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
289	        if (param_.activationType == atb::infer::ActivationType::ACTIVATION_SWIGLU_FORWARD) {
290	            ATB_LOG(INFO) << GetLogPrefix() << "create SwigluForward AclnnRunner";
291	            return std::make_shared<SwigluForwardAclnnRunner>(param_);
292	        } else if (param_.activationType == atb::infer::ActivationType::ACTIVATION_GELU) {
293	            ATB_LOG(INFO) << GetLogPrefix() << "create Gelu AclnnRunner";
294	            return std::make_shared<GeluAclnnRunner>(param_);
295	        } else {
296	            ATB_LOG(INFO) << GetLogPrefix() << "create Activation AclnnRunner";
297	            return std::make_shared<ActivationAclnnRunner>(param_);
298	        }
299	    }
300	    return std::make_shared<ActivationOpsRunner>(param_);
301	}
