40	template <> Status CreateOperation(const infer::ElewiseParam &opParam, Operation **operation)
41	{
42	    if (operation == nullptr) {
43	        return ERROR_INVALID_PARAM;
44	    }
45	
46	    if (Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
47	        if (opParam.elewiseType == infer::ElewiseParam::ElewiseType::ELEWISE_DYNAMIC_QUANT) {
48	            if (AclnnDynamicQuantRunner::LoadMethod() != NO_ERROR) {
49	                ATB_LOG(ERROR) << "Load aclnn function failed, please check your CANN version.";
50	                return ERROR_CANN_ERROR;
51	            }
52	        } else if (opParam.elewiseType == infer::ElewiseParam::ElewiseType::ELEWISE_QUANT_PER_CHANNEL) {
53	            if (AclnnAscendQuantRunner::LoadMethod() != NO_ERROR) {
54	                ATB_LOG(ERROR) << "Load aclnn function failed, please check your CANN version.";
55	                return ERROR_CANN_ERROR;
56	            }
57	        }
58	    }
59	
60	    OP_PARAM_RSV_CHECK(opParam);
61	    OP_PARAM_RSV_CHECK(opParam.mulsParam);
62	    OP_PARAM_RSV_CHECK(opParam.quantParam);
63	    if ((!GetSingleton<Config>().Is910B()) &&
64	        (opParam.elewiseType == infer::ElewiseParam::ElewiseType::ELEWISE_DEQUANT_PER_CHANNEL)) {
65	        ATB_LOG(ERROR) << "Elewise dequant only support Atlas 800I A2 inference product";
66	        return ERROR_INVALID_PARAM;
67	    }
68	    if ((!GetSingleton<Config>().Is910B() &&
69	         Mki::PlatformInfo::Instance().GetPlatformType() != Mki::PlatformType::ASCEND_950) &&
70	        (opParam.elewiseType == infer::ElewiseParam::ElewiseType::ELEWISE_QUANT)) {
71	        ATB_LOG(ERROR) << "Elewise quant is not supported on this product series.";
72	        return ERROR_INVALID_PARAM;
73	    }
74	    if (opParam.elewiseType == infer::ElewiseParam::ElewiseType::ELEWISE_DYNAMIC_QUANT &&
75	        opParam.quantParam.asymmetric) {
76	        ATB_LOG(ERROR) << "Elewise dynamic quant doesn't support asymmetric";
77	        return ERROR_INVALID_PARAM;
78	    }
79	    if (opParam.elewiseType <= infer::ElewiseParam::ElewiseType::ELEWISE_UNDEFINED ||
80	        opParam.elewiseType >= infer::ElewiseParam::ElewiseType::ELEWISE_TYPE_MAX) {
81	        ATB_LOG(ERROR) << "Please enter the correct elewiseType";
82	        return ERROR_INVALID_PARAM;
83	    }
84	    Status status = ElewiseAclnnRunner::LoadMethod();
85	    if (status != NO_ERROR) {
86	        ATB_LOG(ERROR) << "Load Aclnn functions failed!";
87	        return ERROR_INVALID_PARAM;
88	    }
89	    *operation = new (std::nothrow) ElewiseOperation(opParam);
90	    if (*operation == nullptr) {
91	        ATB_LOG(ERROR) << "failed to new operation";
92	        return ERROR_OUT_OF_HOST_MEMORY;
93	    }
94	    return NO_ERROR;
95	}
