299	                                                  outTensors[TENSOR_IDX_ZERO].desc.shape)) {
300	                    ATB_LOG(ERROR) << GetLogPrefix() << "IN_TENSOR_1's shape should match IN_TENSOR_2's shape";
301	                    return ERROR_INVALID_TENSOR_DIM;
302	                }
303	            }
304	            break;
305	        default:
306	            return NO_ERROR;
307	    }
308	    return NO_ERROR;
309	}
310	
311	Status ElewiseOperation::InferShapeImplCast(const SVector<TensorDesc> &inTensorDescs,
312	                                            SVector<TensorDesc> &outTensorDescs) const
313	{
314	    aclDataType dtype = inTensorDescs.at(TENSOR_IDX_ZERO).dtype;
315	    if (param_.outTensorType == ACL_DT_UNDEFINED) {
316	        outTensorDescs.at(TENSOR_IDX_ZERO).dtype = (dtype == ACL_FLOAT) ? ACL_FLOAT16 : ACL_FLOAT;
317	    } else if (param_.outTensorType == ACL_FLOAT16 || param_.outTensorType == ACL_FLOAT ||
318	               param_.outTensorType == ACL_INT32 || param_.outTensorType == ACL_INT64 ||
319	               param_.outTensorType == ACL_BF16) {
320	        outTensorDescs.at(TENSOR_IDX_ZERO).dtype = param_.outTensorType;
321	    } else {
322	        ATB_LOG(WARN) << "ElewiseOperation InferShapeImpl cast: no matched input desc.";
323	        return ERROR_INVALID_PARAM;
324	    }
325	    return NO_ERROR;
326	}
327	
328	Status ElewiseOperation::InferShapeImplQuant(const SVector<TensorDesc> &inTensorDescs,
329	                                             SVector<TensorDesc> &outTensorDescs) const
330	{
331	    uint64_t intensorZeroDimNum = inTensorDescs.at(TENSOR_IDX_ZERO).shape.dimNum;
332	    int64_t intensorZeroLastDim = inTensorDescs.at(TENSOR_IDX_ZERO).shape.dims[intensorZeroDimNum - 1];
333	    if (intensorZeroLastDim % THIRTY_TWO != 0) {
334	        ATB_LOG(ERROR) << "ElewiseOperation InferShapeImpl quant: last dim is not 32 bytes align.";
335	        return ERROR_INVALID_TENSOR_DIM;
336	    }
337	    aclDataType dtype = inTensorDescs.at(TENSOR_IDX_ZERO).dtype;
338	    if (dtype == ACL_FLOAT16) {
339	        outTensorDescs.at(TENSOR_IDX_ZERO).dtype = ACL_INT8;
340	        return NO_ERROR;
341	    } else {
342	        ATB_LOG(WARN) << "ElewiseOperation InferShapeImpl quant: no matched input desc.";
343	        return ERROR_INVALID_PARAM;
344	    }
345	}
