347	Status ElewiseOperation::InferShapeImplQuantAscend950(const SVector<TensorDesc> &inTensorDescs,
348	                                                      SVector<TensorDesc> &outTensorDescs) const
349	{
350	    aclDataType dtype0 = inTensorDescs.at(TENSOR_IDX_ZERO).dtype;
351	    if ((dtype0 == ACL_FLOAT) || (dtype0 == ACL_FLOAT16) || (dtype0 == ACL_BF16)) {
352	        outTensorDescs.at(TENSOR_IDX_ZERO).dtype =
353	            param_.outTensorType == ACL_DT_UNDEFINED ? ACL_INT8 : param_.outTensorType;
354	        return NO_ERROR;
355	    } else {
356	        ATB_LOG(WARN) << "ElewiseOperation InferShapeImplQuantAscend950: no matched input desc.";
357	        return ERROR_INVALID_PARAM;
358	    }
359	}
360	
361	
362	Status ElewiseOperation::InferShapeImplDynamicQuant(const SVector<TensorDesc> &inTensorDescs,
363	                                                    SVector<TensorDesc> &outTensorDescs) const
364	{
365	    if (inTensorDescs.at(TENSOR_IDX_ZERO).shape.dimNum < 2) { // 2: min support dims
366	        ATB_LOG(ERROR) << "InferShapeImplDynamicQuant: input dims must greater than or equal to 2.";
367	        return ERROR_INVALID_TENSOR_DIM_NUM;
368	    }
369	    aclDataType dtype = inTensorDescs.at(TENSOR_IDX_ZERO).dtype;
370	    if (dtype == ACL_FLOAT16) {
371	        if (GetSingleton<Config>().Is910B() && !InferShapeCheckDynamicQuant(inTensorDescs)) {
372	            ATB_LOG(ERROR) << "In Atlas 800I A2 inference product, ElewiseOperation InferShapeImplDynamicQuant:"
373	                           << " when the dtype of the first tensor is float16,"
374	                           << " the size of the last dimension does not exceed 26624.";
375	            return ERROR_INVALID_TENSOR_DIM;
376	        }
377	        if (!GetSingleton<Config>().Is910B() && !InferShapeCheckDynamicQuant310P(inTensorDescs)) {
378	            ATB_LOG(ERROR) << "In Atlas inference products, ElewiseOperation InferShapeImplDynamicQuant:"
379	                           << " when the dtype of the first tensor is float16,"
380	                           << " the size of the last dimension does not exceed 4096.";
381	            return ERROR_INVALID_TENSOR_DIM;
382	        }
383	        outTensorDescs.at(TENSOR_IDX_ZERO).dtype = ACL_INT8;
384	        outTensorDescs.at(TENSOR_IDX_ONE) = inTensorDescs.at(TENSOR_IDX_ZERO);
385	        outTensorDescs.at(TENSOR_IDX_ONE).dtype = ACL_FLOAT;
386	        outTensorDescs.at(TENSOR_IDX_ONE).shape.dimNum--;
387	        if (param_.quantParam.asymmetric) {
388	            outTensorDescs.at(TENSOR_IDX_TWO) = outTensorDescs.at(TENSOR_IDX_ONE);
389	        }
390	    } else if (dtype == ACL_BF16) {
391	        if (GetSingleton<Config>().Is910B() && !InferShapeCheckDynamicQuant(inTensorDescs)) {
392	            ATB_LOG(ERROR) << "In Atlas 800I A2 inference product, ElewiseOperation InferShapeImplDynamicQuant:"
393	                           << " when the dtype of the first tensor is BF16,"
394	                           << " the size of the last dimension does not exceed 7552.";
395	            return ERROR_INVALID_TENSOR_DIM;
396	        }
397	        outTensorDescs.at(TENSOR_IDX_ZERO).dtype = ACL_INT8;
398	        outTensorDescs.at(TENSOR_IDX_ONE) = inTensorDescs.at(TENSOR_IDX_ZERO);
399	        outTensorDescs.at(TENSOR_IDX_ONE).dtype = ACL_FLOAT;
400	        outTensorDescs.at(TENSOR_IDX_ONE).shape.dimNum--;
401	    } else {
402	        ATB_LOG(WARN) << "ElewiseOperation InferShapeImplDynamicQuant: inTensor only support FP16 and BF16 now.";
403	        return ERROR_INVALID_PARAM;
404	    }
405	    if (param_.outTensorType == ACL_HIFLOAT8 || param_.outTensorType == ACL_FLOAT8_E5M2 ||
406	        param_.outTensorType == ACL_FLOAT8_E4M3FN) {
407	        outTensorDescs.at(TENSOR_IDX_ZERO).dtype = param_.outTensorType;
408	    }
409	    return NO_ERROR;
410	}
411	
412	Status ElewiseOperation::InferShapeCommon(const SVector<TensorDesc> &inTensorDescs,
413	                                          SVector<TensorDesc> &outTensorDescs) const
414	{
415	    infer::ElewiseParam::ElewiseType type = param_.elewiseType;
416	    aclDataType dtype0 = inTensorDescs.at(TENSOR_IDX_ZERO).dtype;
417	    aclDataType dtype1 = inTensorDescs.at(TENSOR_IDX_ONE).dtype;
418	    if (dtype0 != dtype1) {
419	        ATB_LOG(WARN) << "ElewiseOperation InferShapeCommon: unsupported input internsor.";
420	        return ERROR_INVALID_PARAM;
421	    }
422	
423	    uint64_t dimNum0 = inTensorDescs.at(TENSOR_IDX_ZERO).shape.dimNum;
424	    uint64_t dimNum1 = inTensorDescs.at(TENSOR_IDX_ONE).shape.dimNum;
425	    uint64_t largerSize = (dimNum0 >= dimNum1) ? dimNum0 : dimNum1;
426	    outTensorDescs.at(TENSOR_IDX_ZERO).shape.dimNum = largerSize;
427	    int64_t idx = 0;
428	    while (idx < static_cast<int64_t>(largerSize)) {
429	        auto dimIdxOut = static_cast<int64_t>(largerSize) - idx - 1;
430	        auto dimIdx0 = static_cast<int64_t>(dimNum0) - idx - 1;
431	        auto dimIdx1 = static_cast<int64_t>(dimNum1) - idx - 1;
432	        auto dim0 = dimIdx0 < 0 ? 1 : inTensorDescs.at(0).shape.dims[dimIdx0];
433	        auto dim1 = dimIdx1 < 0 ? 1 : inTensorDescs.at(1).shape.dims[dimIdx1];
434	        if (dim0 != 1 && dim1 != 1 && dim0 != dim1) {
435	            ATB_LOG(WARN) << "ElewiseOperation InferShapeCommon: cannot broadcast this dim.";
436	            return ERROR_INVALID_TENSOR_DIM;
437	        }
438	        auto dimOut = dim0 >= dim1 ? dim0 : dim1;
439	        outTensorDescs.at(0).shape.dims[dimIdxOut] = dimOut;
440	        idx++;
441	    }
442	
443	    if (type == infer::ElewiseParam::ELEWISE_LESS || type == infer::ElewiseParam::ELEWISE_GREATER ||
444	        type == infer::ElewiseParam::ELEWISE_EQUAL) {
445	        outTensorDescs.at(0).dtype = ACL_INT8;
446	    }
447	
448	    return NO_ERROR;
449	}
450	
451	Status ElewiseOperation::InferShapeImplQuantChannel(const SVector<TensorDesc> &inTensorDescs,
452	                                                    SVector<TensorDesc> &outTensorDescs) const
453	{
454	    (void)inTensorDescs;
455	    outTensorDescs.at(TENSOR_IDX_ZERO).dtype = ACL_INT8;
456	    return NO_ERROR;
457	}
458	
459	Status ElewiseOperation::InferShapeImplDequantChannel(const SVector<TensorDesc> &inTensorDescs,
460	                                                      SVector<TensorDesc> &outTensorDescs) const
461	{
462	    aclDataType dtype0 = inTensorDescs.at(TENSOR_IDX_ZERO).dtype;
463	    aclDataType dtype1 = inTensorDescs.at(TENSOR_IDX_ONE).dtype;
464	    aclDataType dtype2 = inTensorDescs.at(TENSOR_IDX_TWO).dtype;
465	    if ((dtype0 == ACL_INT8) && (dtype1 == ACL_FLOAT16) && (dtype2 == ACL_INT8)) {
466	        outTensorDescs.at(TENSOR_IDX_ZERO).dtype = ACL_FLOAT16;
467	        return NO_ERROR;
468	    } else {
469	        ATB_LOG(WARN) << "ElewiseOperation InferShapeImpl dequant channel: no matched input desc.";
470	        return ERROR_INVALID_PARAM;
471	    }
472	}
473	
474	SVector<bool> ElewiseOperation::GetEmptyInTensorPermissions() const
475	{
476	    SVector<bool> v;
477	
478	    // quant_per_channel dequant_per_channel intensor[2] allows null
479	    if (GetInputNum() == TENSOR_NUM_THREE) {
480	        SVector<bool> emptyTensorPerms(GetInputNum(), false);
481	        emptyTensorPerms.at(TENSOR_NUM_THREE - 1) = true;
482	        return emptyTensorPerms;
483	    }
484	
485	    return v;
486	}
487	
488	bool ElewiseOperation::InferShapeCheckDynamicQuant(const SVector<TensorDesc> &inTensorDescs) const
489	{
490	    uint64_t dimNumZeroTensor = inTensorDescs.at(TENSOR_IDX_ZERO).shape.dimNum;
491	    int64_t lastDim = inTensorDescs.at(TENSOR_IDX_ZERO).shape.dims[dimNumZeroTensor - 1];
492	    if (inTensorDescs.at(TENSOR_IDX_ZERO).dtype == ACL_FLOAT16 && lastDim > MAX_VALUE1) {
493	        return false;
494	    }
495	
496	    if (inTensorDescs.at(TENSOR_IDX_ZERO).dtype == ACL_BF16 && lastDim > MAX_VALUE2) {
497	        return false;
498	    }
499	    return true;
500	}
501	
502	bool ElewiseOperation::InferShapeCheckDynamicQuant310P(const SVector<TensorDesc> &inTensorDescs) const
503	{
504	    uint64_t dimNumZeroTensor = inTensorDescs.at(TENSOR_IDX_ZERO).shape.dimNum;
505	    int64_t lastDim = inTensorDescs.at(TENSOR_IDX_ZERO).shape.dims[dimNumZeroTensor - 1];
506	    if (lastDim > MAX_VALUE3) {
507	        return false;
508	    }
509	    return true;
510	}
