512	std::shared_ptr<Runner> ElewiseOperation::CreateRunner(Context &context) const
513	{
514	    (void)context;
515	    if (param_.elewiseType == infer::ElewiseParam::ElewiseType::ELEWISE_DYNAMIC_QUANT &&
516	        Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
517	        return std::make_shared<AclnnDynamicQuantRunner>(param_);
518	    } else if (param_.elewiseType == infer::ElewiseParam::ElewiseType::ELEWISE_QUANT_PER_CHANNEL &&
519	               Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
520	        return std::make_shared<AclnnAscendQuantRunner>(param_);
521	    }
522	    std::unordered_set<infer::ElewiseParam::ElewiseType> aclnnOpType = {
523	        infer::ElewiseParam::ElewiseType::ELEWISE_CAST,    infer::ElewiseParam::ElewiseType::ELEWISE_MULS,
524	        infer::ElewiseParam::ElewiseType::ELEWISE_COS,     infer::ElewiseParam::ElewiseType::ELEWISE_SIN,
525	        infer::ElewiseParam::ElewiseType::ELEWISE_ADD,     infer::ElewiseParam::ElewiseType::ELEWISE_LESS,
526	        infer::ElewiseParam::ElewiseType::ELEWISE_MUL,     infer::ElewiseParam::ElewiseType::ELEWISE_GREATER,
527	        infer::ElewiseParam::ElewiseType::ELEWISE_REALDIV, infer::ElewiseParam::ElewiseType::ELEWISE_LOGICAL_NOT,
528	        infer::ElewiseParam::ElewiseType::ELEWISE_QUANT,   infer::ElewiseParam::ElewiseType::ELEWISE_SUB,
529	    };
530	    if (aclnnOpType.find(param_.elewiseType) != aclnnOpType.end() &&
531	        Mki::PlatformInfo::Instance().GetPlatformType() == Mki::PlatformType::ASCEND_950) {
532	        return std::make_shared<ElewiseAclnnRunner>(param_);
533	    }
534	    return std::make_shared<ElewiseOpsRunner>(param_);
535	}
