50	inline aclTensor *In(const AclNNVariantPack &variantPack) { return variantPack.aclInTensors.at(IN_TENSOR_IDX)->tensor; }
51	inline aclTensor *Out(const AclNNVariantPack &variantPack) { return variantPack.aclOutTensors.at(OUT_TENSOR_IDX)->tensor; }
