53	ActivationAclnnRunner::KernelAdapters 
54	ActivationAclnnRunner::MakeAdaptersByType(const infer::ActivationParam &param) {
55	    switch (param.activationType) {
56	        case infer::ActivationType::ACTIVATION_FAST_GELU:
57	        return {
58	            "fast_gelu",
59	            [](const AclNNVariantPack &vp, uint64_t *wsSize, aclOpExecutor **executor) {
60	                return ActivationAclnnRunner::fastGeluGetWorkspaceSizeFunc_(In(vp), Out(vp), wsSize, executor);
61	            },
62	            [](void *ws, uint64_t wsSize, aclOpExecutor *executor, aclrtStream stream) {
63	                return ActivationAclnnRunner::fastGeluExecuteFunc_(ws, wsSize, executor, stream);
64	            }
65	        };
66	
67	        case infer::ActivationType::ACTIVATION_GELU:
68	        return {
69	            "gelu",
70	            [mode = (param.geluMode == infer::ActivationParam::GeLUMode::NONE_MODE) ? 0 : 1](
71	                const AclNNVariantPack &vp, uint64_t *wsSize, aclOpExecutor **executor) {
72	                int64_t modeTmp = mode;
73	                return ActivationAclnnRunner::geluGetWorkspaceSizeFunc_(In(vp), &modeTmp, Out(vp), wsSize,
74	                                                                        executor);
75	            },
76	            [](void *ws, uint64_t wsSize, aclOpExecutor *executor, aclrtStream stream) {
77	                return ActivationAclnnRunner::geluExecuteFunc_(ws, wsSize, executor, stream);
78	            }
79	        };
80	
81	        case infer::ActivationType::ACTIVATION_LOG:
82	        return {
83	            "log",
84	            [](const AclNNVariantPack &vp, uint64_t *wsSize, aclOpExecutor **executor) {
85	                return ActivationAclnnRunner::logGetWorkspaceSizeFunc_(In(vp), Out(vp), wsSize, executor);
86	            },
87	            [](void *ws, uint64_t wsSize, aclOpExecutor *executor, aclrtStream stream) {
88	                return ActivationAclnnRunner::logExecuteFunc_(ws, wsSize, executor, stream);
89	            }
90	        };
91	
92	        case infer::ActivationType::ACTIVATION_RELU:
93	        return {
94	            "relu",
95	            [](const AclNNVariantPack &vp, uint64_t *wsSize, aclOpExecutor **executor) {
96	                return ActivationAclnnRunner::reluGetWorkspaceSizeFunc_(In(vp), Out(vp), wsSize, executor);
97	            },
98	            [](void *ws, uint64_t wsSize, aclOpExecutor *executor, aclrtStream stream) {
99	                return ActivationAclnnRunner::reluExecuteFunc_(ws, wsSize, executor, stream);
100	            }
101	        };
102	
103	        case infer::ActivationType::ACTIVATION_SIGMOID:
104	        return {
105	            "sigmoid",
106	            [](const AclNNVariantPack &vp, uint64_t *wsSize, aclOpExecutor **executor) {
107	                return ActivationAclnnRunner::sigmoidGetWorkspaceSizeFunc_(In(vp), Out(vp), wsSize, executor);
108	            },
109	            [](void *ws, uint64_t wsSize, aclOpExecutor *executor, aclrtStream stream) {
110	                return ActivationAclnnRunner::sigmoidExecuteFunc_(ws, wsSize, executor, stream);
111	            }
112	        };
113	
114	        case infer::ActivationType::ACTIVATION_SWISH:
115	        return {
116	            "swish",
117	            [scale = param.scale](const AclNNVariantPack &vp, uint64_t *wsSize, aclOpExecutor **executor) {
118	                float scaleTmp = scale;
119	                aclScalar *scalar = aclCreateScalar(&scaleTmp, aclDataType::ACL_FLOAT);
120	                aclnnStatus aclnnstatus =
121	                    ActivationAclnnRunner::swishGetWorkspaceSizeFunc_(In(vp), scalar, Out(vp), wsSize, executor);
122	                aclnnStatus aclnnDestroyStatus = aclDestroyScalar(scalar);
123	                if (aclnnDestroyStatus != ACL_SUCCESS) {
124	                    ATB_LOG(ERROR) << "Failed to destroy scalar, ret = " << aclnnDestroyStatus;
125	                    return aclnnDestroyStatus;
126	                }
127	                return aclnnstatus;
128	            },
129	            [](void *ws, uint64_t wsSize, aclOpExecutor *executor, aclrtStream stream) {
130	                return ActivationAclnnRunner::swishExecuteFunc_(ws, wsSize, executor, stream);
131	            }
132	        };
133	
134	        default:
135	        return {
136	            "unsupported",
137	            [](const AclNNVariantPack &, uint64_t *, aclOpExecutor **) {
138	                return ACLNN_ERR_INNER_FIND_KERNEL_ERROR;
139	            },
140	            [](void *, uint64_t, aclOpExecutor *, aclrtStream) {
141	                return ACLNN_ERR_INNER_FIND_KERNEL_ERROR;
142	            }
143	        };
144	    }
145	}
