169	
170	    ret = CallAclCreateTensor(atbInTensor.desc.shape, atbInTensor.desc.shape, atbInTensor, aclnnInTensorPtr,
171	                              atbInTensor.desc.dtype);
172	    if (ret != NO_ERROR) {
173	        ATB_LOG(ERROR) << GetLogPrefix() << "Create aclTensor using AclCreateTensor failed.";
174	        return ret;
175	    }
176	    aclnnInTensorPtr->tensorIdx = static_cast<int>(IN_TENSOR_IDX);
177	    aclnnInTensorPtr->needUpdateTensorDataPtr = true;
178	    this->aclnnVariantPack_.aclInTensors[IN_TENSOR_IDX] = aclnnInTensorPtr;
179	
180	    this->aclnnVariantPack_.aclOutTensors.reserve(OUT_TENSOR_NUM);
181	    this->aclnnVariantPack_.aclOutTensors.resize(OUT_TENSOR_NUM);
182	    std::shared_ptr<AclNNTensor> aclnnOutTensorPtr = std::make_shared<AclNNTensor>();
183	    ATB_LOG(INFO) << GetLogPrefix() << "Processing outTensor[0]...";
184	    atb::Tensor atbOutTensor = {};
185	    atbOutTensor = runnerVariantPack.outTensors.at(OUT_TENSOR_IDX);
186	    aclnnOutTensorPtr->atbTensor = atbOutTensor;
187	    aclnnOutTensorPtr->strides = GetCopyTensorStride(atbOutTensor.desc.shape);
188	    ret = CallAclCreateTensor(atbOutTensor.desc.shape, atbOutTensor.desc.shape, atbOutTensor, aclnnOutTensorPtr,
189	                              atbOutTensor.desc.dtype);
190	    if (ret != NO_ERROR) {
191	        ATB_LOG(ERROR) << GetLogPrefix() << "Create aclTensor using AclCreateTensor failed.";
192	        return ret;
193	    }
194	    aclnnOutTensorPtr->tensorIdx = static_cast<int>(OUT_TENSOR_IDX);
195	    aclnnOutTensorPtr->needUpdateTensorDataPtr = true;
196	    this->aclnnVariantPack_.aclOutTensors[OUT_TENSOR_IDX] = aclnnOutTensorPtr;
197	
198	    return NO_ERROR;
199	}
