201	aclnnStatus ActivationAclnnRunner::SetAclNNWorkspaceExecutor()
202	{
203	    ATB_LOG(INFO) << GetLogPrefix() << "Aclnn activation setup start.";
204	    KernelAdapters kernelAdapter = MakeAdaptersByType(param_);
205	    this->getWs_ = std::move(kernelAdapter.getWs);
206	    this->execFn_ = std::move(kernelAdapter.exec);
207	    if (!getWs_) {
208	        ATB_LOG(ERROR) << GetLogPrefix() << "Alcnn GetWorkspaceSizeFunc is null!";
209	        return ACLNN_ERR_INNER_FIND_KERNEL_ERROR;
210	    }
211	    ATB_LOG(INFO) << GetLogPrefix() << "aclnn activation type: " << param_.activationType
212	                  << ", aclInTensor size: " << this->aclnnVariantPack_.aclInTensors.size()
213	                  << ", aclOutTensor size: " << this->aclnnVariantPack_.aclOutTensors.size();
214	
215	    aclOpExecutor *raw_executor_ptr = this->aclnnExecutor_.get();
216	
217	    aclnnStatus ret =
218	        this->getWs_(this->aclnnVariantPack_, &(this->atbVariantPack_.workspaceBufferSize), &raw_executor_ptr);
219	    if (ret != ACL_SUCCESS) {
220	        ATB_LOG(ERROR) << GetLogPrefix() << "aclnnGetWorkspaceSizeFunc failed, error: " << ret;
221	        return ret;
222	    }
223	    this->aclnnExecutor_.reset(raw_executor_ptr, [this](aclOpExecutor *ptr) {
224	        if (ptr && this->executorRepeatable_)
225	            aclDestroyAclOpExecutor(ptr); // 可复用时需要手动销毁aclOpExecutor
226	    });
227	    ATB_LOG(INFO) << GetLogPrefix() << "WorkspaceSize: " << this->atbVariantPack_.workspaceBufferSize;
228	    return ret;
229	}
