231	Status ActivationAclnnRunner::LaunchAclnnKernel()
232	{
233	    ATB_LOG(INFO) << GetLogPrefix() << "LaunchAclnnKernel called.";
234	    void *executeStream = GetExecuteStream(this->atbVariantPack_.context);
235	    aclnnStatus ret = this->execFn_(this->atbVariantPack_.workspaceBuffer,
236	                                    this->atbVariantPack_.workspaceBufferSize,
237	                                    this->aclnnExecutor_.get(), executeStream);
238	    if (ret != ACL_SUCCESS) {
239	        ATB_LOG(ERROR) << GetLogPrefix() << "Launch kernel failed with error: " << ret;
240	        return ERROR_CANN_ERROR;
241	    }
242	    ATB_LOG(INFO) << GetLogPrefix() << "LaunchAclnnKernel success.";
243	    return NO_ERROR;
244	}
