270	        status = LoadFromSharedObjectFile("aclnnReluGetWorkspaceSize", "aclnnRelu",
271	                                          ActivationAclnnRunner::reluGetWorkspaceSizeFunc_,
272	                                          ActivationAclnnRunner::reluExecuteFunc_);
273	        if (status != NO_ERROR) { once_status = status; return; }
274	
275	        status = LoadFromSharedObjectFile("aclnnSigmoidGetWorkspaceSize", "aclnnSigmoid",
276	                                          ActivationAclnnRunner::sigmoidGetWorkspaceSizeFunc_,
277	                                          ActivationAclnnRunner::sigmoidExecuteFunc_);
278	        if (status != NO_ERROR) { once_status = status; return; }
279	
280	        status = LoadFromSharedObjectFile("aclnnSwishGetWorkspaceSize", "aclnnSwish",
